  p=next(x for x in parents if x['county_fips']==u['county_fips']);unit_inventory.append({'source':u,'complete_original_candidate_row':source_rows[u['key']],'candidate_definitions':next(c['candidates'] for c in native['2024-senate'] if c['county']==u['county']),'complete_publication_object_ref':{'scope':'2024-senate','source_id':u['source_id'],'county':u['county']},'parent':p['county_fips'],'shared_resource_refs':{'parent_fips':p['county_fips'],'resource_object_pointer':'parents/'+p['county_fips']+'/shared_acquired_resources','state_service':'state-election-service','census_zip_receipt':'census-vtd-zip','relationship':'acquired qualified shared context only'},'priority':u['in_minimum80'],'gaps':{**p['gaps'],'source_key':u['key'],'literal_label':u['native_label'],'unit_type':u['unit_type'],'source_position':[u['source_id'],u['page'],u['line']]},'physical_leaf_polygon_match':None,'current_native_reporting_ID_match':None})
